package com.example.lending.application.service;

import com.example.lending.application.port.in.GetMonthlyStatsUseCase;
import com.example.lending.application.port.out.LoadLoansInPeriodPort;
import com.example.lending.domain.Loan;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

@Service
@Transactional(readOnly = true)
public class GetMonthlyStatsService implements GetMonthlyStatsUseCase {

    private final LoadLoansInPeriodPort loadLoansInPeriodPort;

    public GetMonthlyStatsService(LoadLoansInPeriodPort loadLoansInPeriodPort) {
        this.loadLoansInPeriodPort = loadLoansInPeriodPort;
    }

    @Override
    public MonthlyStats getMonthlyStats(MonthlyStatsQuery query) {
        YearMonth month = YearMonth.of(query.year(), query.month());
        LocalDate from = month.atDay(1);
        LocalDate to = month.atEndOfMonth();

        List<Loan> loaned = loadLoansInPeriodPort.loadLoanedBetween(from, to);
        List<Loan> returned = loadLoansInPeriodPort.loadReturnedBetween(from, to);

        // 연체료는 Loan 의 규칙(주말 기한 포함)을 그대로 쓴다.
        long overdueCount = returned.stream().filter(loan -> loan.lateFee() > 0).count();
        long lateFeeTotal = returned.stream().mapToLong(Loan::lateFee).sum();
        return new MonthlyStats(query.year(), query.month(), loaned.size(), returned.size(), overdueCount,
                lateFeeTotal);
    }
}

